import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import ItemList from 'flarum/common/utils/ItemList';
import dayjs from 'dayjs';
import { FORMAT } from '../utils/createDateRangeUtil';
export default class CustomDateRangeModal extends FormModal {
  start = dayjs().startOf('day').format(FORMAT);
  end = dayjs().startOf('day').format(FORMAT);
  pendingApply = null;
  oninit(vnode) {
    super.oninit(vnode);
    const params = app.search?.state?.params?.() ?? {};
    if (params.start) this.start = params.start;
    if (params.end) this.end = params.end;
  }
  onremove(vnode) {
    super.onremove(vnode);
    if (this.pendingApply) {
      this.attrs.onApply?.(this.pendingApply);
      this.pendingApply = null;
    }
  }
  className() {
    return 'CustomDateRangeModal Modal--small';
  }
  title() {
    return app.translator.trans('glowingblue-date-filters.forum.custom_date_range_modal.title');
  }
  content() {
    return [m("div", {
      className: "Modal-body"
    }, this.body()), m("div", {
      className: "Modal-footer"
    }, this.footer())];
  }
  body() {
    const today = dayjs().startOf('day');
    const maxEnd = today.format(FORMAT);
    return m("div", null, m("label", {
      htmlFor: "start"
    }, app.translator.trans('glowingblue-date-filters.forum.custom_date_range_modal.start_date_label')), m("br", null), m("input", {
      type: "date",
      id: "start",
      name: "range-start",
      value: this.start,
      max: maxEnd,
      oninput: e => {
        this.start = e.target.value;
        const startDate = dayjs(this.start, FORMAT, true);
        if (!startDate.isValid()) return;
        const endDate = dayjs(this.end, FORMAT, true);
        if (endDate.isValid() && endDate.isBefore(startDate)) {
          this.end = this.start;
        }
      }
    }), m("br", null), m("br", null), m("label", {
      htmlFor: "end"
    }, app.translator.trans('glowingblue-date-filters.forum.custom_date_range_modal.end_date_label')), m("br", null), m("input", {
      type: "date",
      id: "end",
      name: "range-end",
      value: this.end,
      max: maxEnd,
      oninput: e => {
        this.end = e.target.value;
        const endDate = dayjs(this.end, FORMAT, true);
        if (!endDate.isValid()) return;
        const startDate = dayjs(this.start, FORMAT, true);
        if (startDate.isValid() && startDate.isAfter(endDate)) {
          this.start = this.end;
        }
      }
    }));
  }
  footer() {
    return m('[', null, this.footerItems().toArray());
  }
  footerItems() {
    const items = new ItemList();
    items.add('cancel', m(Button, {
      className: "Button",
      onclick: () => this.hide()
    }, app.translator.trans('glowingblue-date-filters.forum.custom_date_range_modal.cancel_button')));
    items.add('apply', m(Button, {
      className: "Button Button--primary",
      disabled: !this.isValid(),
      onclick: () => {
        if (!this.isValid()) return;
        this.pendingApply = {
          start: this.start,
          end: this.end
        };
        this.hide();
      }
    }, app.translator.trans('glowingblue-date-filters.forum.custom_date_range_modal.apply_button')));
    return items;
  }
  isValid() {
    const startDate = dayjs(this.start, FORMAT, true);
    const endDate = dayjs(this.end, FORMAT, true);
    return startDate.isValid() && endDate.isValid() && !endDate.isBefore(startDate);
  }
}
flarum.reg.add('glowingblue-date-filters', 'forum/components/CustomDateRangeModal', CustomDateRangeModal);